args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?spouse ?spouseLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Lou_Breslow dbo:spouse ?spouse .
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER(lang(?spouseLabel) = "en") }
  OPTIONAL {
    ?spouse dbo:birthPlace ?birthPlace .
    OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
  }
}

